            if line[i] == '.': colorize_range(colors, i, i+1, '\x1b[31m')
            else: colorize_range(colors, i, i+1, '\x1b[3;34m')
    for m in re.finditer(r'\b(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}\b', line):
