    if opts['builtin']: apply_rest(line, colors)
    if 'urls' in opts['enabled']: apply_url(line, colors)
    if 'uuids' in opts['enabled']: apply_uuid(line, colors)
    if 'ip-addresses' in opts['enabled']: apply_ip(line, colors)
    if 'pointers' in opts['enabled']: apply_pointer(line, colors)
    if 'dates' in opts['enabled']:
