    if 'processes' in opts['enabled']: apply_process(line, colors)
    if 'paths' in opts['enabled']: apply_path(line, colors)
    if 'key-value-pairs' in opts['enabled']: apply_kv(line, colors)
    if 'quotes' in opts['enabled']: apply_quotes(line, colors)
    if opts['builtin']:
