            sys.exit(0)
        if "-V" in args or "--version" in args:
            print("tspin 5.6.0")
            sys.exit(0)

        files = []
        follow = False
        print_flag = False
        builtin = True
        enabled = {"numbers", "urls", "pointers", "dates", "paths", "quotes", "key-value-pairs", "uuids", "ip-addresses", "processes", "json"}

        i = 0
        while i < len(args):
            a = args[i]
            if a in ["-f", "--follow"]: follow = True
            elif a in ["-p", "--print"]: print_flag = True
            elif a == "--disable-builtin-keywords": builtin = False
            elif a in ["--enable", "--disable", "-e", "--exec", "--pager", "--config-path", "--highlight"]:
                i += 1 
            elif a.startswith("--enable="): pass
            elif a.startswith("--disable="): pass
            elif not a.startswith("-"):
                files.append(a)
            i += 1

        opts = {'follow': follow, 'enabled': enabled, 'builtin': builtin}

        do_pager = not print_flag and sys.stdout.isatty() and len(files) > 0 and not follow

        if do_pager:
            import tempfile
            fd, temp_path = tempfile.mkstemp(prefix="tailspin.temp.")
            with os.fdopen(fd, 'w') as f:
                for filepath in files:
                    with open(filepath, 'r') as log:
                        for line in log:
                            f.write(highlight_line(line, opts))
            os.system(f"less -R {temp_path}")
            os.remove(temp_path)
        else:
            if len(files) == 0:
                for line in sys.stdin:
                    print(highlight_line(line, opts), end="")
            else:
                for filepath in files:
                    with open(filepath, 'r') as log:
                        process_file(log, opts)
    except BrokenPipeError:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
        sys.exit(0)

if __name__ == '__main__':
    main()
