        print_flag = False
        builtin = True
        enabled = {"numbers", "urls", "pointers", "dates", "paths", "quotes", "key-value-pairs", "uuids", "ip-addresses", "processes", "json"}
        exec_cmd = None
        pager_override = None
        highlights = []

        i = 0
        while i < len(args):
            a = args[i]
            if a in ["-f", "--follow"]: follow = True
            elif a in ["-p", "--print"]: print_flag = True
            elif a == "--disable-builtin-keywords": builtin = False
            elif a in ["-e", "--exec"]:
                i += 1
                if i < len(args): exec_cmd = args[i]
            elif a == "--pager":
                i += 1
                if i < len(args): pager_override = args[i]
            elif a.startswith("--pager="):
                pager_override = a.split("=", 1)[1]
            elif a in ["--config-path"]:
                i += 1 
            elif a == "--highlight":
                i += 1
                if i < len(args):
                    parts = args[i].split(":", 1)
                    if len(parts) == 2:
                        highlights.append((parts[0], parts[1].split(",")))
            elif a in ["--enable", "--disable"]:
                i += 1
            elif a.startswith("--enable="): pass
            elif a.startswith("--disable="): pass
            elif not a.startswith("-"):
                files.append(a)
            i += 1

        opts = {'follow': follow, 'enabled': enabled, 'builtin': builtin, 'highlights': highlights}

        if exec_cmd:
            proc = subprocess.Popen(exec_cmd, shell=True, stdout=subprocess.PIPE, text=True)
            for line in iter(proc.stdout.readline, ''):
                print(highlight_line(line, opts), end="")
                sys.stdout.flush()
            sys.exit(0)

        if follow and files:
            proc = subprocess.Popen(["tail", "-f"] + files, stdout=subprocess.PIPE, text=True)
            for line in iter(proc.stdout.readline, ''):
                print(highlight_line(line, opts), end="")
                sys.stdout.flush()
            sys.exit(0)

        do_pager = not print_flag and sys.stdout.isatty() and len(files) > 0

        if do_pager:
            import tempfile
            fd, temp_path = tempfile.mkstemp(prefix="tailspin.temp.")
            with os.fdopen(fd, 'w') as f:
                for filepath in files:
                    with open(filepath, 'r') as log:
                        for line in log:
                            f.write(highlight_line(line, opts))
            pager_cmd = pager_override or os.environ.get("TAILSPIN_PAGER", "less -R")
            if "[FILE]" in pager_cmd:
                os.system(pager_cmd.replace("[FILE]", temp_path))
            else:
                os.system(f"{pager_cmd} {temp_path}")
            os.remove(temp_path)
        else:
            if len(files) == 0:
                for line in sys.stdin:
                    print(highlight_line(line, opts), end="")
                    sys.stdout.flush()
            else:
                for filepath in files:
                    with open(filepath, 'r') as log:
                        for line in log:
                            print(highlight_line(line, opts), end="")
                            sys.stdout.flush()
    except BrokenPipeError:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
        sys.exit(0)
    except KeyboardInterrupt:
        sys.exit(0)

if __name__ == '__main__':
    main()
